/* Palette: #1e1e2f (bg), #2a2a40 (card), #f0f0f5 (text), #6c63ff (accent), #ff6b6b (accent2) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  background: #1e1e2f;
  color: #f0f0f5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: #2a2a40;
  padding: 2rem;
  border-radius: 1.5rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 500px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.5px;
}

.preview {
  width: 100%;
  aspect-ratio: 1 / 1;
  max-height: 200px;
  border-radius: 1rem;
  background: #000000;
  border: 2px solid #3a3a55;
  transition: background 0.2s ease;
}

.hex {
  font-size: 1.5rem;
  font-weight: 500;
  text-align: center;
  font-family: monospace;
  letter-spacing: 1px;
  color: #f0f0f5;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.slider-group {
  display: grid;
  grid-template-columns: 4rem 1fr 3rem;
  align-items: center;
  gap: 0.5rem;
}

.slider-group label {
  font-size: 1rem;
  font-weight: 500;
}

.slider-group input[type="range"] {
  width: 100%;
  height: 8px;
  -webkit-appearance: none;
  appearance: none;
  background: #3a3a55;
  border-radius: 4px;
  outline: none;
  cursor: pointer;
}

.slider-group input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #6c63ff;
  border: 2px solid #f0f0f5;
  transition: transform 0.1s ease, background 0.2s ease;
}

.slider-group input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #6c63ff;
  border: 2px solid #f0f0f5;
  transition: transform 0.1s ease, background 0.2s ease;
}

.slider-group input[type="range"]:hover::-webkit-slider-thumb {
  background: #7b73ff;
  transform: scale(1.1);
}

.slider-group input[type="range"]:hover::-moz-range-thumb {
  background: #7b73ff;
  transform: scale(1.1);
}

.slider-group input[type="range"]:focus-visible {
  outline: 2px solid #6c63ff;
  outline-offset: 4px;
}

.slider-group input[type="range"]:active::-webkit-slider-thumb {
  background: #5a52e0;
  transform: scale(0.95);
}

.slider-group input[type="range"]:active::-moz-range-thumb {
  background: #5a52e0;
  transform: scale(0.95);
}

.value {
  font-size: 1rem;
  font-weight: 500;
  text-align: right;
  font-family: monospace;
  color: #c0c0d0;
}

.random-btn {
  background: #6c63ff;
  color: #f0f0f5;
  border: none;
  padding: 0.875rem 1.5rem;
  font-size: 1.125rem;
  font-weight: 600;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  letter-spacing: 0.5px;
}

.random-btn:hover {
  background: #7b73ff;
  box-shadow: 0 4px 12px rgba(108, 99, 255, 0.4);
}

.random-btn:focus-visible {
  outline: 3px solid #ff6b6b;
  outline-offset: 2px;
}

.random-btn:active {
  background: #5a52e0;
  transform: scale(0.98);
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .slider-group {
    grid-template-columns: 3.5rem 1fr 2.5rem;
  }
  .hex {
    font-size: 1.25rem;
  }
}

const redSlider = document.getElementById('red');
const greenSlider = document.getElementById('green');
const blueSlider = document.getElementById('blue');
const redValue = document.getElementById('redValue');
const greenValue = document.getElementById('greenValue');
const blueValue = document.getElementById('blueValue');
const preview = document.getElementById('preview');
const hexDisplay = document.getElementById('hexDisplay');
const randomBtn = document.getElementById('randomBtn');

function updateColor() {
  const r = parseInt(redSlider.value, 10);
  const g = parseInt(greenSlider.value, 10);
  const b = parseInt(blueSlider.value, 10);

  redValue.textContent = r;
  greenValue.textContent = g;
  blueValue.textContent = b;

  const hex = '#' + [r, g, b].map(c => c.toString(16).padStart(2, '0')).join('');
  preview.style.backgroundColor = hex;
  hexDisplay.textContent = hex;
}

function randomize() {
  redSlider.value = Math.floor(Math.random() * 256);
  greenSlider.value = Math.floor(Math.random() * 256);
  blueSlider.value = Math.floor(Math.random() * 256);
  updateColor();
}

redSlider.addEventListener('input', updateColor);
greenSlider.addEventListener('input', updateColor);
blueSlider.addEventListener('input', updateColor);
randomBtn.addEventListener('click', randomize);

updateColor();
